@final
def _get_axis_resolvers(self, axis: str) -> dict[str, Series | MultiIndex]:
    axis_index = getattr(self, axis)
    d = {}
    prefix = axis[0]
    for i, name in enumerate(axis_index.names):
        if name is not None:
            key = level = name
        else:
            key = f'{prefix}level_{i}'
            level = i
        level_values = axis_index.get_level_values(level)
        s = level_values.to_series()
        s.index = axis_index
        d[key] = s
    if isinstance(axis_index, MultiIndex):
        dindex = axis_index
    else:
        dindex = axis_index.to_series()
    d[axis] = dindex
    return d

@final
def _get_index_resolvers(self) -> dict[Hashable, Series | MultiIndex]:
    from pandas.core.computation.parsing import clean_column_name
    d: dict[str, Series | MultiIndex] = {}
    for axis_name in self._AXIS_ORDERS:
        d.update(self._get_axis_resolvers(axis_name))
    return {clean_column_name(k): v for k, v in d.items() if not isinstance(k, int)}

@final
def _get_cleaned_column_resolvers(self) -> dict[Hashable, Series]:
    """
        Return the special character free column resolvers of a dataframe.

        Column names with special characters are 'cleaned up' so that they can
        be referred to by backtick quoting.
        Used in :meth:`DataFrame.eval`.
        """
    from pandas.core.computation.parsing import clean_column_name
    if isinstance(self, ABCSeries):
        return {clean_column_name(self.name): self}
    return {clean_column_name(k): v for k, v in self.items() if not isinstance(k, int)}

