@final
def swapaxes(self, axis1: Axis, axis2: Axis, copy: bool_t | None=None) -> Self:
    """
        Interchange axes and swap values axes appropriately.

        Returns
        -------
        same as input
        """
    warnings.warn(f"'{type(self).__name__}.swapaxes' is deprecated and will be removed in a future version. Please use '{type(self).__name__}.transpose' instead.", FutureWarning, stacklevel=find_stack_level())
    i = self._get_axis_number(axis1)
    j = self._get_axis_number(axis2)
    if i == j:
        return self.copy(deep=copy and (not using_copy_on_write()))
    mapping = {i: j, j: i}
    new_axes = [self._get_axis(mapping.get(k, k)) for k in range(self._AXIS_LEN)]
    new_values = self._values.swapaxes(i, j)
    if using_copy_on_write() and self._mgr.is_single_block and isinstance(self._mgr, BlockManager):
        new_mgr = ndarray_to_mgr(new_values, new_axes[0], new_axes[1], dtype=None, copy=False, typ='block')
        assert isinstance(new_mgr, BlockManager)
        assert isinstance(self._mgr, BlockManager)
        new_mgr.blocks[0].refs = self._mgr.blocks[0].refs
        new_mgr.blocks[0].refs.add_reference(new_mgr.blocks[0])
        return self._constructor(new_mgr).__finalize__(self, method='swapaxes')
    elif (copy or copy is None) and self._mgr.is_single_block:
        new_values = new_values.copy()
    return self._constructor(new_values, *new_axes, copy=False).__finalize__(self, method='swapaxes')

@final
def _rename(self, mapper: Renamer | None=None, *, index: Renamer | None=None, columns: Renamer | None=None, axis: Axis | None=None, copy: bool_t | None=None, inplace: bool_t=False, level: Level | None=None, errors: str='ignore') -> Self | None:
    if mapper is None and index is None and (columns is None):
        raise TypeError('must pass an index to rename')
    if index is not None or columns is not None:
        if axis is not None:
            raise TypeError("Cannot specify both 'axis' and any of 'index' or 'columns'")
        if mapper is not None:
            raise TypeError("Cannot specify both 'mapper' and any of 'index' or 'columns'")
    elif axis and self._get_axis_number(axis) == 1:
        columns = mapper
    else:
        index = mapper
    self._check_inplace_and_allows_duplicate_labels(inplace)
    result = self if inplace else self.copy(deep=copy and (not using_copy_on_write()))
    for axis_no, replacements in enumerate((index, columns)):
        if replacements is None:
            continue
        ax = self._get_axis(axis_no)
        f = common.get_rename_function(replacements)
        if level is not None:
            level = ax._get_level_number(level)
        if not callable(replacements):
            if ax._is_multi and level is not None:
                indexer = ax.get_level_values(level).get_indexer_for(replacements)
            else:
                indexer = ax.get_indexer_for(replacements)
            if errors == 'raise' and len(indexer[indexer == -1]):
                missing_labels = [label for index, label in enumerate(replacements) if indexer[index] == -1]
                raise KeyError(f'{missing_labels} not found in axis')
        new_index = ax._transform_index(f, level=level)
        result._set_axis_nocheck(new_index, axis=axis_no, inplace=True, copy=False)
        result._clear_item_cache()
    if inplace:
        self._update_inplace(result)
        return None
    else:
        return result.__finalize__(self, method='rename')

