    """Check if we do need a multi reindex."""
    return common.count_not_none(*axes.values()) == self._AXIS_LEN and method is None and (level is None) and (not self._is_mixed_type) and (not (self.ndim == 2 and len(self.dtypes) == 1 and isinstance(self.dtypes.iloc[0], ExtensionDtype)))

@final
def _reindex_with_indexers(self, reindexers, fill_value=None, copy: bool_t | None=False, allow_dups: bool_t=False) -> Self:
    """allow_dups indicates an internal call here"""
    new_data = self._mgr
    for axis in sorted(reindexers.keys()):
        index, indexer = reindexers[axis]
        baxis = self._get_block_manager_axis(axis)
        if index is None:
            continue
        index = ensure_index(index)
        if indexer is not None:
            indexer = ensure_platform_int(indexer)
        new_data = new_data.reindex_indexer(index, indexer, axis=baxis, fill_value=fill_value, allow_dups=allow_dups, copy=copy)
        copy = False
    if (copy or copy is None) and new_data is self._mgr and (not using_copy_on_write()):
        new_data = new_data.copy(deep=copy)
    elif using_copy_on_write() and new_data is self._mgr:
        new_data = new_data.copy(deep=False)
    return self._constructor(new_data).__finalize__(self)

@final
def __getattr__(self, name: str):
    """
        After regular attribute access, try looking up the name
        This allows simpler access to columns for interactive use.
        """
    if name not in self._internal_names_set and name not in self._metadata and (name not in self._accessors) and self._info_axis._can_hold_identifiers_and_holds_name(name):
        return self[name]
    return object.__getattribute__(self, name)

@final
def __setattr__(self, name: str, value) -> None:
    """
        After regular attribute access, try setting the name
        This allows simpler access to columns for interactive use.
        """
    try:
        object.__getattribute__(self, name)
        return object.__setattr__(self, name, value)
    except AttributeError:
        pass
    if name in self._internal_names_set:
        object.__setattr__(self, name, value)
    elif name in self._metadata:
        object.__setattr__(self, name, value)
    else:
        try:
            existing = getattr(self, name)
            if isinstance(existing, Index):
                object.__setattr__(self, name, value)
            elif name in self._info_axis:
                self[name] = value
            else:
                object.__setattr__(self, name, value)
        except (AttributeError, TypeError):
            if isinstance(self, ABCDataFrame) and is_list_like(value):
                warnings.warn("Pandas doesn't allow columns to be created via a new attribute name - see https://pandas.pydata.org/pandas-docs/stable/indexing.html#attribute-access", stacklevel=find_stack_level())
            object.__setattr__(self, name, value)

