@final
def _clip_with_scalar(self, lower, upper, inplace: bool_t=False):
    if lower is not None and np.any(isna(lower)) or (upper is not None and np.any(isna(upper))):
        raise ValueError('Cannot use an NA value as a clip threshold')
    result = self
    mask = self.isna()
    if lower is not None:
        cond = mask | (self >= lower)
        result = result.where(cond, lower, inplace=inplace)
    if upper is not None:
        cond = mask | (self <= upper)
        result = self if inplace else result
        result = result.where(cond, upper, inplace=inplace)
    return result

@final
def _clip_with_one_bound(self, threshold, method, axis, inplace):
    if axis is not None:
        axis = self._get_axis_number(axis)
    if is_scalar(threshold) and is_number(threshold):
        if method.__name__ == 'le':
            return self._clip_with_scalar(None, threshold, inplace=inplace)
        return self._clip_with_scalar(threshold, None, inplace=inplace)
    if not isinstance(threshold, ABCSeries) and is_list_like(threshold):
        if isinstance(self, ABCSeries):
            threshold = self._constructor(threshold, index=self.index)
        else:
            threshold = self._align_for_op(threshold, axis, flex=None)[1]
    if is_list_like(threshold):
        fill_value = np.inf if method.__name__ == 'le' else -np.inf
        threshold_inf = threshold.fillna(fill_value)
    else:
        threshold_inf = threshold
    subset = method(threshold_inf, axis=axis) | isna(self)
    return self.where(subset, threshold, axis=axis, inplace=inplace)

@doc(_shared_docs['compare'], klass=_shared_doc_kwargs['klass'])
def compare(self, other, align_axis: Axis=1, keep_shape: bool_t=False, keep_equal: bool_t=False, result_names: Suffixes=('self', 'other')):
    if type(self) is not type(other):
        cls_self, cls_other = (type(self).__name__, type(other).__name__)
        raise TypeError(f"can only compare '{cls_self}' (not '{cls_other}') with '{cls_self}'")
    mask = ~((self == other) | self.isna() & other.isna())
    mask.fillna(True, inplace=True)
    if not keep_equal:
        self = self.where(mask)
        other = other.where(mask)
    if not keep_shape:
        if isinstance(self, ABCDataFrame):
            cmask = mask.any()
            rmask = mask.any(axis=1)
            self = self.loc[rmask, cmask]
            other = other.loc[rmask, cmask]
        else:
            self = self[mask]
            other = other[mask]
    if not isinstance(result_names, tuple):
        raise TypeError(f"Passing 'result_names' as a {type(result_names)} is not supported. Provide 'result_names' as a tuple instead.")
    if align_axis in (1, 'columns'):
        axis = 1
    else:
        axis = self._get_axis_number(align_axis)
    diff = concat([self, other], axis=axis, keys=result_names)
    if axis >= self.ndim:
        return diff
    ax = diff._get_axis(axis)
    ax_names = np.array(ax.names)
    ax.names = np.arange(len(ax_names))
    order = list(range(1, ax.nlevels)) + [0]
    if isinstance(diff, ABCDataFrame):
        diff = diff.reorder_levels(order, axis=axis)
    else:
        diff = diff.reorder_levels(order)
    diff._get_axis(axis=axis).names = ax_names[order]
    indices = np.arange(diff.shape[axis]).reshape([2, diff.shape[axis] // 2]).T.flatten()
    diff = diff.take(indices, axis=axis)
    return diff

@final
def _align_frame(self, other: DataFrame, join: AlignJoin='outer', axis: Axis | None=None, level=None, copy: bool_t | None=None, fill_value=None, method=None, limit: int | None=None, fill_axis: Axis=0) -> tuple[Self, DataFrame, Index | None]:
    join_index, join_columns = (None, None)
    ilidx, iridx = (None, None)
    clidx, cridx = (None, None)
    is_series = isinstance(self, ABCSeries)
    if (axis is None or axis == 0) and (not self.index.equals(other.index)):
        join_index, ilidx, iridx = self.index.join(other.index, how=join, level=level, return_indexers=True)
    if (axis is None or axis == 1) and (not is_series) and (not self.columns.equals(other.columns)):
        join_columns, clidx, cridx = self.columns.join(other.columns, how=join, level=level, return_indexers=True)
    if is_series:
        reindexers = {0: [join_index, ilidx]}
    else:
        reindexers = {0: [join_index, ilidx], 1: [join_columns, clidx]}
    left = self._reindex_with_indexers(reindexers, copy=copy, fill_value=fill_value, allow_dups=True)
    right = other._reindex_with_indexers({0: [join_index, iridx], 1: [join_columns, cridx]}, copy=copy, fill_value=fill_value, allow_dups=True)
    if method is not None:
        left = left.fillna(method=method, axis=fill_axis, limit=limit)
        right = right.fillna(method=method, axis=fill_axis, limit=limit)
    return (left, right, join_index)

@final
def _align_series(self, other: Series, join: AlignJoin='outer', axis: Axis | None=None, level=None, copy: bool_t | None=None, fill_value=None, method=None, limit: int | None=None, fill_axis: Axis=0) -> tuple[Self, Series, Index | None]:
    is_series = isinstance(self, ABCSeries)
    if copy and using_copy_on_write():
        copy = False
    if not is_series and axis is None or axis not in [None, 0, 1]:
        raise ValueError('Must specify axis=0 or 1')
    if is_series and axis == 1:
        raise ValueError('cannot align series to a series other than axis 0')
    if not axis:
        if self.index.equals(other.index):
            join_index, lidx, ridx = (None, None, None)
        else:
            join_index, lidx, ridx = self.index.join(other.index, how=join, level=level, return_indexers=True)
        if is_series:
            left = self._reindex_indexer(join_index, lidx, copy)
        elif lidx is None or join_index is None:
            left = self.copy(deep=copy)
        else:
            left = self._constructor(self._mgr.reindex_indexer(join_index, lidx, axis=1, copy=copy))
        right = other._reindex_indexer(join_index, ridx, copy)
    else:
        fdata = self._mgr
        join_index = self.axes[1]
        lidx, ridx = (None, None)
        if not join_index.equals(other.index):
            join_index, lidx, ridx = join_index.join(other.index, how=join, level=level, return_indexers=True)
        if lidx is not None:
            bm_axis = self._get_block_manager_axis(1)
            fdata = fdata.reindex_indexer(join_index, lidx, axis=bm_axis)
        if copy and fdata is self._mgr:
            fdata = fdata.copy()
        left = self._constructor(fdata)
        if ridx is None:
            right = other.copy(deep=copy)
        else:
            right = other.reindex(join_index, level=level)
    fill_na = notna(fill_value) or method is not None
    if fill_na:
        left = left.fillna(fill_value, method=method, limit=limit, axis=fill_axis)
        right = right.fillna(fill_value, method=method, limit=limit)
    return (left, right, join_index)

@final
def _where(self, cond, other=lib.no_default, inplace: bool_t=False, axis: Axis | None=None, level=None):
    """
        Equivalent to public method `where`, except that `other` is not
        applied as a function even if callable. Used in __setitem__.
        """
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if axis is not None:
        axis = self._get_axis_number(axis)
    cond = common.apply_if_callable(cond, self)
    if isinstance(cond, NDFrame):
        if cond.ndim == 1 and self.ndim == 2:
            cond = cond._constructor_expanddim({i: cond for i in range(len(self.columns))}, copy=False)
            cond.columns = self.columns
        cond = cond.align(self, join='right', copy=False)[0]
    else:
        if not hasattr(cond, 'shape'):
            cond = np.asanyarray(cond)
        if cond.shape != self.shape:
            raise ValueError('Array conditional must be same shape as self')
        cond = self._constructor(cond, **self._construct_axes_dict(), copy=False)
    fill_value = bool(inplace)
    cond = cond.fillna(fill_value)
    msg = 'Boolean array expected for the condition, not {dtype}'
    if not cond.empty:
        if not isinstance(cond, ABCDataFrame):
            if not is_bool_dtype(cond):
                raise ValueError(msg.format(dtype=cond.dtype))
        else:
            for _dt in cond.dtypes:
                if not is_bool_dtype(_dt):
                    raise ValueError(msg.format(dtype=_dt))
            if cond._mgr.any_extension_types:
                cond = cond._constructor(cond.to_numpy(dtype=bool, na_value=fill_value), **cond._construct_axes_dict())
    else:
        cond = cond.astype(bool)
    cond = -cond if inplace else cond
    cond = cond.reindex(self._info_axis, axis=self._info_axis_number, copy=False)
    if isinstance(other, NDFrame):
        if other.ndim <= self.ndim:
            other = self.align(other, join='left', axis=axis, level=level, fill_value=None, copy=False)[1]
            if axis is None and (not other._indexed_same(self)):
                raise InvalidIndexError
            if other.ndim < self.ndim:
                other = other._values
                if axis == 0:
                    other = np.reshape(other, (-1, 1))
                elif axis == 1:
                    other = np.reshape(other, (1, -1))
                other = np.broadcast_to(other, self.shape)
        else:
            raise NotImplementedError('cannot align with a higher dimensional NDFrame')
    elif not isinstance(other, (MultiIndex, NDFrame)):
        other = extract_array(other, extract_numpy=True)
    if isinstance(other, (np.ndarray, ExtensionArray)):
        if other.shape != self.shape:
            if self.ndim != 1:
                raise ValueError('other must be the same shape as self when an ndarray')
        else:
            other = self._constructor(other, **self._construct_axes_dict(), copy=False)
    if axis is None:
        axis = 0
    if self.ndim == getattr(other, 'ndim', 0):
        align = True
    else:
        align = self._get_axis_number(axis) == 1
    if inplace:
        new_data = self._mgr.putmask(mask=cond, new=other, align=align)
        result = self._constructor(new_data)
        return self._update_inplace(result)
    else:
        new_data = self._mgr.where(other=other, cond=cond, align=align)
        result = self._constructor(new_data)
        return result.__finalize__(self)

